'use strict';

const fs = require('fs');
const path = require('path');

const FONT_DIR = path.join(__dirname, 'fonts');

/** Read a font fixture as a Node Buffer (non-ArrayBuffer input). */
function readFont(fileName) {
    return fs.readFileSync(path.join(FONT_DIR, fileName));
}

/**
 * Change the tag of the first matching table directory entry of an sfnt font.
 * This is used to synthesize otherwise hard-to-produce table combinations.
 */
function renameTableTag(fontBuffer, fromTag, toTag) {
    const copy = Buffer.from(fontBuffer);
    const numTables = copy.readUInt16BE(4);
    for (let i = 0; i < numTables; i++) {
        const entryOffset = 12 + i * 16;
        if (copy.toString('latin1', entryOffset, entryOffset + 4) === fromTag) {
            copy.write(toTag, entryOffset, 4, 'latin1');
            return copy;
        }
    }
    throw new Error('Table ' + fromTag + ' not found in fixture');
}

/** Overwrite the 4 byte sfnt/WOFF signature of a font. */
function withSignature(fontBuffer, signature) {
    const copy = Buffer.from(fontBuffer);
    copy.write(signature, 0, 4, 'latin1');
    return copy;
}

let opentype;
let parse;

beforeAll(async () => {
    opentype = await import('../src/opentype.mjs');
    parse = opentype.parse;
});

afterEach(() => {
    jest.restoreAllMocks();
});

describe('module surface', () => {
    test('exposes the documented public API', () => {
        expect(typeof opentype.parse).toBe('function');
        expect(opentype._parse).toBeDefined();
        expect(typeof opentype._parse.getTag).toBe('function');
        expect(typeof opentype.Font).toBe('function');
        expect(typeof opentype.Glyph).toBe('function');
        expect(typeof opentype.Path).toBe('function');
        expect(typeof opentype.BoundingBox).toBe('function');
        expect(typeof opentype.load).toBe('function');
        expect(typeof opentype.loadSync).toBe('function');
        expect(opentype.parse).not.toBe(opentype._parse);
    });

    test('re-exports the low-level byte parsing helpers as _parse', () => {
        const bytes = new Uint8Array([
            0x41, 0x42, 0x43, 0x44, // "ABCD"
            0x00, 0x01, 0x00, 0x00, // 65536
            0xff, 0xfe,             // -2
        ]);
        const view = new DataView(bytes.buffer);

        expect(opentype._parse.getTag(view, 0)).toBe('ABCD');
        // OpenType data is big endian, regardless of host endianness.
        expect(opentype._parse.getULong(view, 4)).toBe(65536);
        expect(opentype._parse.getUShort(view, 4)).toBe(1);
        expect(opentype._parse.getShort(view, 8)).toBe(-2);
        expect(typeof opentype._parse.Parser).toBe('function');
    });

    test('re-exports the Font, Glyph, Path and BoundingBox classes used by parse results', () => {
        const font = parse(readFont('Changa-Regular.ttf'));
        const glyph = font.glyphs.get(4);
        const box = glyph.getBoundingBox();

        expect(font).toBeInstanceOf(opentype.Font);
        expect(glyph).toBeInstanceOf(opentype.Glyph);
        expect(glyph.path).toBeInstanceOf(opentype.Path);
        expect(box).toBeInstanceOf(opentype.BoundingBox);

        const standalonePath = new opentype.Path();
        standalonePath.moveTo(0, 0);
        standalonePath.lineTo(10, 20);
        expect(standalonePath.commands.length).toBe(2);
        expect(standalonePath.getBoundingBox()).toEqual({x1: 0, y1: 0, x2: 10, y2: 20});

        const standaloneBox = new opentype.BoundingBox();
        standaloneBox.addPoint(3, 4);
        standaloneBox.addPoint(-1, 9);
        expect(standaloneBox).toEqual({x1: -1, y1: 4, x2: 3, y2: 9});
    });

    test('can construct a Font directly through the re-exported class', () => {
        const font = new opentype.Font({
            familyName: 'TestFamily',
            styleName: 'Book',
            unitsPerEm: 1000,
            ascender: 800,
            descender: -200
        });

        expect(font.unitsPerEm).toBe(1000);
        expect(font.getEnglishName('fontFamily')).toBe('TestFamily');
        expect(font.names.windows.fontSubfamily.en).toBe('Book');
        expect(font.numGlyphs).toBeUndefined();
        expect(font.glyphs.length).toBe(0);
    });
});

