describe('parsing CFF based fonts', () => {
    test('parses an OTTO font with CFF outlines', () => {
        const font = parse(readFont('AbrilFatface-Regular.otf'));

        expect(font.outlinesFormat).toBe('cff');
        expect(font.tables.cff).toBeDefined();
        expect(font.tables.glyf).toBeUndefined();
        expect(font.numGlyphs).toBe(424);
        expect(font.glyphs.length).toBe(424);

        const glyph = font.charToGlyph('A');
        expect(glyph.index).toBe(20);
        expect(glyph.name).toBe('A');
        expect(glyph.advanceWidth).toBe(694);
        expect(glyph.path.commands.length).toBe(21);
    });

    test('parses GDEF, GPOS and GSUB tables with their scripts', () => {
        const font = parse(readFont('SourceSansPro-Regular.otf'));

        expect(font.tables.gdef).toBeDefined();
        expect(font.tables.gpos.scripts.map((script) => script.tag)).toEqual(
            expect.arrayContaining(['DFLT', 'latn'])
        );
        expect(font.tables.gsub.scripts.map((script) => script.tag)).toEqual(
            expect.arrayContaining(['DFLT', 'latn'])
        );
        expect(font.tables.gsub.features.length).toBeGreaterThan(0);
        expect(font.tables.gsub.features.map((feature) => feature.tag)).toEqual(
            expect.arrayContaining(['ccmp', 'liga'])
        );
    });

    test('parses a CFF2 font together with its variation tables', () => {
        const font = parse(readFont('TestHVAROne.otf'));

        expect(font.outlinesFormat).toBe('cff');
        expect(font.tables.cff2).toBeDefined();
        expect(font.tables.fvar.axes.map((axis) => axis.tag)).toEqual(['wght']);
        expect(font.tables.hvar).toBeDefined();
        expect(font.numGlyphs).toBe(4);
        expect(font.charToGlyph('A').path.commands.length).toBeGreaterThan(0);
    });
