            .toThrow('This is a CFF2 font, but FDArray information is missing');
    });

    test('rejects a FontSet containing more than one font', () => {
        const bytes = new Uint8Array([
            1, 0, 4, 1,             // header
            0, 2, 1, 1, 2, 3, 65, 66, // Name INDEX with two names
            0, 2, 1, 1, 1, 1,       // Top DICT INDEX with two empty DICTs
            0, 0,                   // String INDEX
            0, 0                    // Global Subr INDEX
        ]);

        expect(() => cff.parse(toDataView(bytes), 0, {tables: {}}, {}))
            .toThrow('CFF table has too many fonts in \'FontSet\' - count of fonts NameIndex.length = 2');
