 * Behavioral tests for src/tables/cff.mjs.
 *
 * The module is ESM, so the production modules are loaded with dynamic
 * `import()` in `beforeAll`. The public contract is:
 *   - cff.make(glyphs, options) -> a `CFF ` table record
 *   - cff.parse(data, start, font, opt) -> mutates `font` with CFF data
 *   - applyPaintType(font, path) -> number, optionally styles the path
 */

const fs = require('fs');
const path = require('path');

let cff;
let applyPaintType;
let glyphset;
let Glyph;
let Path;

beforeAll(async () => {
    const cffModule = await import('../../src/tables/cff.mjs');
    cff = cffModule.default;
    applyPaintType = cffModule.applyPaintType;
    glyphset = (await import('../../src/glyphset.mjs')).default;
    Glyph = (await import('../../src/glyph.mjs')).default;
    Path = (await import('../../src/path.mjs')).default;
