// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function pathOf(defs) {
    const p = new Path();
    for (const d of defs) {
        switch (d[0]) {
            case 'M': p.moveTo(d[1], d[2]); break;
            case 'L': p.lineTo(d[1], d[2]); break;
            case 'C': p.curveTo(d[1], d[2], d[3], d[4], d[5], d[6]); break;
            case 'Q': p.quadraticCurveTo(d[1], d[2], d[3], d[4]); break;
            case 'Z': p.close(); break;
            default: throw new Error('Unknown path command ' + d[0]);
        }
    }
    return p;
}

function makeGlyphSet(glyphDefs) {
    const glyphs = glyphDefs.map((def) => new Glyph({
        name: def.name,
        unicode: def.unicode,
        advanceWidth: def.advanceWidth,
        path: def.path || new Path()
    }));
    return new glyphset.GlyphSet({unitsPerEm: 1000}, glyphs);
}

// .notdef is skipped when the charset is written, so it always comes first.
function basicGlyphDefs() {
    return [
        {name: '.notdef', advanceWidth: 500},
        {
            name: 'A',
            unicode: 65,
            advanceWidth: 600,
            path: pathOf([
                ['M', 100, 200],
                ['L', 300, 400],
                ['C', 350, 450, 400, 500, 450, 550],
                ['Z']
            ])
        },
        {
            name: 'myGlyph', // not a CFF standard string: exercises the String INDEX
            unicode: 98,
            advanceWidth: 700,
            path: pathOf([
                ['M', -10, -20],
                ['L', 0, 0],
                ['Z'],
                ['M', 20, 20],
                ['L', 30, 20],
                ['L', 30, 30],
                ['Z']
            ])
        }
    ];
}

function makeTable(glyphDefs, optionOverrides) {
    const options = Object.assign({
        unitsPerEm: 1000,
        version: 'Version 1.000',
        fullName: 'Generated Test Font',
        familyName: 'Generated Test',
        weightName: 'Regular',
        postScriptName: 'GeneratedTest-Regular',
        fontBBox: [0, 0, 600, 700]
    }, optionOverrides);

    return cff.make(makeGlyphSet(glyphDefs), options);
}

function toBytes(table) {
    return new Uint8Array(table.encode());
}

function toDataView(bytes) {
    return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

function parseBytes(bytes, start, opt, fontOverrides) {
    const font = Object.assign({tables: {}, unitsPerEm: 1000}, fontOverrides);
    cff.parse(toDataView(bytes), start || 0, font, opt || {});
    return font;
}

// Pull a raw sfnt table out of a fixture font.
function readSfntTable(fileName, tag) {
    const file = path.join(__dirname, '..', 'fonts', fileName);
    const buffer = fs.readFileSync(file);
    const view = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);
    const numTables = view.getUint16(4);
    for (let i = 0; i < numTables; i += 1) {
        const record = 12 + i * 16;
        const recordTag = String.fromCharCode(
            view.getUint8(record),
            view.getUint8(record + 1),
            view.getUint8(record + 2),
            view.getUint8(record + 3)
        );
        if (recordTag === tag) {
            return {
                view,
                offset: view.getUint32(record + 8),
                length: view.getUint32(record + 12)
            };
        }
    }
    throw new Error('Table ' + tag + ' not found in ' + fileName);
}

function parseFixtureTable(fileName, tag, fontOverrides, opt) {
    const {view, offset} = readSfntTable(fileName, tag);
    const font = Object.assign({tables: {}, unitsPerEm: 1000}, fontOverrides);
    cff.parse(view, offset, font, opt || {});
    return font;
}

