describe('cff.parse error handling', () => {
    test('rejects unsupported CFF versions', () => {
        const bytes = new Uint8Array([3, 0, 4, 1]);
        const font = {tables: {}};

        expect(() => cff.parse(toDataView(bytes), 0, font, {}))
            .toThrow('Unsupported CFF table version 3.0');
    });

    test('rejects a CFF2 table with no FDArray', () => {
        // major=2, minor=0, hdrSize=5, topDictLength=0, then a zero-count
        // CFF2 global subr INDEX (ULONG count).
        const bytes = new Uint8Array([2, 0, 5, 0, 0, 0, 0, 0, 0]);
        const font = {tables: {}};

        expect(() => cff.parse(toDataView(bytes), 0, font, {}))
            .toThrow('This is a CFF2 font, but FDArray information is missing');
    });

    test('rejects a FontSet containing more than one font', () => {
        const bytes = new Uint8Array([
            1, 0, 4, 1,             // header
            0, 2, 1, 1, 2, 3, 65, 66, // Name INDEX with two names
            0, 2, 1, 1, 1, 1,       // Top DICT INDEX with two empty DICTs
            0, 0,                   // String INDEX
            0, 0                    // Global Subr INDEX
        ]);

        expect(() => cff.parse(toDataView(bytes), 0, {tables: {}}, {}))
            .toThrow('CFF table has too many fonts in \'FontSet\' - count of fonts NameIndex.length = 2');
    });

    test('rejects an unknown charset format', () => {
        const bytes = new Uint8Array(toBytes(makeTable(basicGlyphDefs())));
        // Locate the custom charset first, then corrupt its format byte.
        const reference = parseBytes(bytes);
        const charsetOffset = reference.tables.cff.topDict.charset;
        expect(charsetOffset).toBeGreaterThan(2);

        const corrupted = new Uint8Array(bytes);
        corrupted[charsetOffset] = 3;

        expect(() => cff.parse(toDataView(corrupted), 0, {tables: {}}, {}))
            .toThrow('Unknown charset format 3');
    });
});

