        const target = {};

        expect(applyPaintType({tables: {}}, target)).toBe(0);
        expect(target).toEqual({});
    });

    test('returns 0 when the top dict has no paintType entry', () => {
        const target = {fill: 'black'};

        expect(applyPaintType({tables: {cff: {topDict: {}}}}, target)).toBe(0);
        expect(target).toEqual({fill: 'black'});
    });

    test('returns a non-stroking paintType without styling the path', () => {
        const target = {};

        expect(applyPaintType({tables: {cff: {topDict: {paintType: 1}}}}, target)).toBe(1);
        expect(target).toEqual({});
    });

    test('styles the path as a stroke for paintType 2', () => {
        const target = {fill: 'black'};

        expect(applyPaintType({
            tables: {cff: {topDict: {paintType: 2, strokeWidth: 42}}}
        }, target)).toBe(2);

        expect(target).toEqual({fill: null, stroke: 'black', strokeWidth: 42});
    });

    test('defaults the stroke width to 0 when it is missing', () => {
        const target = {};

        applyPaintType({tables: {cff: {topDict: {paintType: 2}}}}, target);
        expect(target.strokeWidth).toBe(0);
    });

    test('ignores CFF2 tables when looking for paintType', () => {
        const target = {fill: 'black'};

        expect(applyPaintType({
            tables: {cff2: {topDict: {paintType: 2, strokeWidth: 10}}}
        }, target)).toBe(0);
        expect(target).toEqual({fill: 'black'});
    });

    test('strokes glyph paths produced by parse for a paintType 2 font', () => {
        const defs = [
            {name: '.notdef', advanceWidth: 500},
            {
                name: 'square',
                advanceWidth: 600,
                path: pathOf([
                    ['M', 0, 0],
                    ['L', 100, 0],
                    ['L', 100, 100],
                    ['Z']
                ])
            }
        ];
        const table = makeTable(defs, {topDict: {paintType: 2, strokeWidth: 25}});
        const font = parseBytes(toBytes(table));

        expect(font.tables.cff.topDict.paintType).toBe(2);

        const glyphPath = font.glyphs.get(1).path;
        expect(glyphPath.fill).toBeNull();
        expect(glyphPath.stroke).toBe('black');
        expect(glyphPath.strokeWidth).toBe(25);
        // Stroked contours stay open, so no implicit closePath is emitted.
        expect(glyphPath.commands.map((c) => c.type)).toEqual(['M', 'L', 'L']);
    });

    test('fills and closes contours for a paintType 0 font', () => {
        const defs = [
            {name: '.notdef', advanceWidth: 500},
            {
                name: 'square',
                advanceWidth: 600,
                path: pathOf([
                    ['M', 0, 0],
                    ['L', 100, 0],
                    ['L', 100, 100],
                    ['Z']
                ])
            }
        ];
        const font = parseBytes(toBytes(makeTable(defs)));
        const glyphPath = font.glyphs.get(1).path;

        expect(glyphPath.fill).toBe('black');
        expect(glyphPath.stroke).toBeNull();
        expect(glyphPath.commands.map((c) => c.type)).toEqual(['M', 'L', 'L', 'Z']);
    });
});

