function dataViewOf(bytes) {
    return new DataView(new Uint8Array(bytes).buffer);
}

function buildCmapTable(entries) {
    // entries: [{platformID, encodingID, data: Uint8Array}]
    const headerSize = 4 + entries.length * 8;
    const totalSize = entries.reduce((size, entry) => size + entry.data.length, headerSize);
    const bytes = new Uint8Array(totalSize);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 0, false);
    view.setUint16(2, entries.length, false);

    let offset = headerSize;
    entries.forEach((entry, index) => {
        view.setUint16(4 + index * 8, entry.platformID, false);
        view.setUint16(6 + index * 8, entry.encodingID, false);
        view.setUint32(8 + index * 8, offset, false);
        bytes.set(entry.data, offset);
        offset += entry.data.length;
    });
    return view;
}

function makeFormat4Subtable({segments, glyphIds = [], language = 0}) {
    const segCount = segments.length;
    const length = 16 + segCount * 8 + glyphIds.length * 2;
    const bytes = new Uint8Array(length);
