        view.setUint16(16 + segCount * 8 + i * 2, glyphId, false);
    });
    return bytes;
}

function makeFormat12Subtable(groups, {format = 12, language = 0, reserved = 0} = {}) {
    const bytes = new Uint8Array(16 + groups.length * 12);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, format, false);
