function makeFormat0Subtable({indexMap = [], language = 0, length = 262, extraBytes = 6} = {}) {
    // Keep extra bytes available because length is the full subtable length (262).
    const bytes = new Uint8Array(6 + 256 + extraBytes);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 0, false);
    view.setUint16(2, length, false);
    view.setUint16(4, language, false);
    for (let i = 0; i < 256; i += 1) {
        bytes[6 + i] = indexMap[i] || 0;
    }
    return bytes;
}

function makeFormat14Subtable() {
    const recordCount = 2;
    const recordsOffset = 10;
    const defaultUvsOffset = recordsOffset + recordCount * 11;
    const defaultUvsLength = 4 + 4; // count + one range (uint24 + uint8)
    const nonDefaultUvsOffset = defaultUvsOffset + defaultUvsLength;
    const nonDefaultUvsLength = 4 + 2 * 5; // count + two mappings
    const length = nonDefaultUvsOffset + nonDefaultUvsLength;
    const bytes = new Uint8Array(length);
    const view = new DataView(bytes.buffer);

    view.setUint16(0, 14, false);
    view.setUint32(2, length, false);
    view.setUint32(6, recordCount, false);

    function writeUint24(offset, value) {
        view.setUint8(offset, (value >> 16) & 0xFF);
        view.setUint16(offset + 1, value & 0xFFFF, false);
    }

    // Record 0: default UVS table for variation selector U+FE00.
    writeUint24(recordsOffset, 0xFE00);
    view.setUint32(recordsOffset + 3, defaultUvsOffset, false);
    view.setUint32(recordsOffset + 7, 0, false);

    // Record 1: non-default UVS table for variation selector U+FE01.
    const secondRecord = recordsOffset + 11;
    writeUint24(secondRecord, 0xFE01);
    view.setUint32(secondRecord + 3, 0, false);
    view.setUint32(secondRecord + 7, nonDefaultUvsOffset, false);

    view.setUint32(defaultUvsOffset, 1, false);
    writeUint24(defaultUvsOffset + 4, 0x41);
    view.setUint8(defaultUvsOffset + 7, 2);

    view.setUint32(nonDefaultUvsOffset, 2, false);
    writeUint24(nonDefaultUvsOffset + 4, 0x50);
    view.setUint16(nonDefaultUvsOffset + 7, 100, false);
    writeUint24(nonDefaultUvsOffset + 9, 0x51);
    view.setUint16(nonDefaultUvsOffset + 12, 101, false);

    return bytes;
}

function glyphSet(glyphs) {
    return {
        length: glyphs.length,
        get(index) {
            return glyphs[index];
        }
    };
}

function simpleFormat4() {
    return makeFormat4Subtable({
        segments: [
            {start: 0x41, end: 0x43, delta: -64, rangeOffset: 0},
            {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}
        ]
    });
