        const indexMap = [];
        indexMap[0x41] = 7;
        indexMap[0x80] = 21;
        indexMap[0xC1] = 33;
        const data = buildCmapTable([{
            platformID: 1,
            encodingID: 0,
            data: makeFormat0Subtable({indexMap, language: 1})
        }]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap).toMatchObject({format: 0, length: 262, language: 0});
        expect(cmap.glyphIndexMap[0x41]).toBe(7);
        // 0x80 maps to U+00C4 (macintosh 'Ä'), 0xC1 maps to U+00A1 ('¡').
        expect(cmap.glyphIndexMap[196]).toBe(21);
        expect(cmap.glyphIndexMap[161]).toBe(33);
    });

    it('accepts platform 0 Unicode subtable records', () => {
        const data = buildCmapTable([{platformID: 0, encodingID: 3, data: simpleFormat4()}]);
