    it('prefers the last supported subtable record when several are present', () => {
        const low = makeFormat4Subtable({
            segments: [{start: 0x41, end: 0x41, delta: -64, rangeOffset: 0},
                {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}]
        });
        const high = makeFormat4Subtable({
            segments: [{start: 0x41, end: 0x41, delta: -58, rangeOffset: 0},
                {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}]
        });
        const data = buildCmapTable([
            {platformID: 3, encodingID: 1, data: low},
            {platformID: 0, encodingID: 4, data: high}
        ]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.glyphIndexMap[0x41]).toBe(7);
    });

    it('parses format 14 variation selectors as a supplement to format 4', () => {
        const data = buildCmapTable([
            {platformID: 3, encodingID: 1, data: simpleFormat4()},
            {platformID: 0, encodingID: 5, data: makeFormat14Subtable()}
        ]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.format).toBe(4);
        expect(cmap.glyphIndexMap[0x42]).toBe(2);
        expect(cmap.varSelectorList[0xFE00]).toEqual({
            varSelector: 0xFE00,
            defaultUVS: {
                ranges: [{startUnicodeValue: 0x41, additionalCount: 2}]
            }
        });
        expect(cmap.varSelectorList[0xFE01]).toEqual({
            varSelector: 0xFE01,
            nonDefaultUVS: {
                uvsMappings: {
                    0x50: {unicodeValue: 0x50, glyphID: 100},
                    0x51: {unicodeValue: 0x51, glyphID: 101}
                }
            }
        });
    });

    it('ignores a platform 0/encoding 5 record that is not actually format 14', () => {
        const notFormat14 = makeFormat4Subtable({
            segments: [{start: 0x41, end: 0x41, delta: -64, rangeOffset: 0},
                {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}]
        });
        const data = buildCmapTable([
            {platformID: 3, encodingID: 1, data: simpleFormat4()},
            {platformID: 0, encodingID: 5, data: notFormat14}
        ]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.format).toBe(4);
        expect(cmap.varSelectorList).toBeUndefined();
    });

    it('throws when only an unsupported/format-14-only subtable is available', () => {
        const data = buildCmapTable([{platformID: 0, encodingID: 5, data: makeFormat14Subtable()}]);
        expect(() => parseCmapTable(data, 0)).toThrow('No valid cmap sub-tables found.');
    });

    it('throws for a non-zero cmap version', () => {
        const bytes = new Uint8Array(12);
        const view = new DataView(bytes.buffer);
        view.setUint16(0, 1, false);
        view.setUint16(2, 0, false);

        expect(() => parseCmapTable(view, 0)).toThrow('cmap table version should be 0.');
    });

    it('throws a descriptive error for an unsupported subtable format', () => {
        const bytes = new Uint8Array(4 + 8 + 8);
        const view = new DataView(bytes.buffer);
        view.setUint16(0, 0, false);
        view.setUint16(2, 1, false);
        view.setUint16(4, 3, false);
        view.setUint16(6, 1, false);
        view.setUint32(8, 12, false);
        view.setUint16(12, 6, false); // format 6
        view.setUint16(14, 10, false); // subtable length

        expect(() => parseCmapTable(view, 0)).toThrow(
            'Only format 0 (platformId 1, encodingId 0), 4, 12 and 14 cmap tables are supported ' +
            '(found format 6, platformId 3, encodingId 1).'
        );
    });
});

describe('parseCmapTableFormat0 (exported helper)', () => {
