// ---------------------------------------------------------------------------
// make (makeCmapTable)
// ---------------------------------------------------------------------------

describe('makeCmapTable', () => {
    it('emits a terminator-only format 4 table for an empty glyph set', () => {
        const cmap = makeCmapTable(glyphSet([]));

        expect(cmap).toMatchObject({
            version: 0,
            numTables: 1,
            platformID: 3,
            encodingID: 1,
            offset: 12,
            format: 4,
            language: 0,
            segCountX2: 2,
            searchRange: 2,
            entrySelector: 0,
            rangeShift: 0,
            cmap4Length: 24
        });
        expect(cmap.segments).toEqual([
            {end: 0xFFFF, start: 0xFFFF, delta: 1, offset: 0}
        ]);
    });

    it('creates format 4 segments and merges runs with the same delta', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 32, unicodes: [32]},
            {unicode: 65, unicodes: [65, 66]},
            {unicode: 67, unicodes: [67]}
        ]);
        const cmap = makeCmapTable(glyphs);

        expect(cmap.numTables).toBe(1);
        expect(cmap.format).toBe(4);
        expect(cmap.offset).toBe(12);
        expect(cmap.segments).toEqual([
            {end: 0, start: 0, delta: -0, offset: 0, glyphIndex: 0},
            {end: 32, start: 32, delta: -31, offset: 0, glyphIndex: 1},
            {end: 65, start: 65, delta: -63, offset: 0, glyphIndex: 2},
            {end: 67, start: 66, delta: -64, offset: 0, glyphIndex: 2},
            {end: 0xFFFF, start: 0xFFFF, delta: 1, offset: 0}
        ]);
        expect(cmap.segCountX2).toBe(10);
        expect(cmap.searchRange).toBe(8);
        expect(cmap.entrySelector).toBe(2);
        expect(cmap.rangeShift).toBe(2);
        expect(cmap.cmap4Length).toBe(56);
    });

    it('adds a format 12 subtable when a glyph uses a supplementary-plane codepoint', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 0x1F600, unicodes: [0x1F600]},
            {unicode: 65, unicodes: [65]}
        ]);
        const cmap = makeCmapTable(glyphs);

        expect(cmap).toMatchObject({
            numTables: 2,
            offset: 20,
            format: 4,
            cmap12PlatformID: 3,
            cmap12EncodingID: 10,
            segCountX2: 6,
            searchRange: 4,
            entrySelector: 1,
            rangeShift: 2,
            cmap4Length: 40
        });
        expect(cmap.cmap12Offset).toBe(60);
        expect(cmap.fields.find((field) => field.name === 'cmap12Length').value).toBe(52);
        expect(cmap.fields.find((field) => field.name === 'cmap12Language').value).toBe(0);
        expect(cmap.fields.find((field) => field.name === 'cmap12nGroups').value).toBe(3);
        expect(cmap.fields.filter((field) => field.name.startsWith('cmap12Start_'))).toEqual([
            {name: 'cmap12Start_0', type: 'ULONG', value: 0},
            {name: 'cmap12Start_1', type: 'ULONG', value: 65},
            {name: 'cmap12Start_2', type: 'ULONG', value: 128512}
        ]);
    });

    it('does not merge non-adjacent codepoints', () => {
        const glyphs = glyphSet([
            {unicode: 65, unicodes: [65]},
            {unicode: 67, unicodes: [67]}
        ]);
        const cmap = makeCmapTable(glyphs);
        const mappingSegments = cmap.segments.slice(0, -1);

        expect(mappingSegments).toHaveLength(2);
        expect(mappingSegments[0]).toMatchObject({start: 65, end: 65});
        expect(mappingSegments[1]).toMatchObject({start: 67, end: 67});
    });

    it('encodes a table whose size matches sizeOf and can be parsed back (format 4)', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 32, unicodes: [32]},
            {unicode: 65, unicodes: [65, 66]},
            {unicode: 67, unicodes: [67]}
        ]);
        const cmap = makeCmapTable(glyphs);
        const bytes = cmap.encode();

        expect(bytes).toHaveLength(cmap.sizeOf());
        const parsed = parseCmapTable(dataViewOf(bytes), 0);
        expect(parsed.format).toBe(4);
        expect(parsed.cmap4Length).toBeUndefined();
        expect(parsed.glyphIndexMap).toEqual({
            0: 0, 32: 1, 65: 2, 66: 2, 67: 3
        });
    });

    it('encodes a supplementary table so that it round-trips through format 12', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 0x1F600, unicodes: [0x1F600]},
            {unicode: 65, unicodes: [65]}
        ]);
        const cmap = makeCmapTable(glyphs);
        const bytes = cmap.encode();

        expect(bytes).toHaveLength(cmap.sizeOf());
        const parsed = parseCmapTable(dataViewOf(bytes), 0);
        expect(parsed.format).toBe(12);
        expect(parsed.groupCount).toBe(3);
        expect(parsed.glyphIndexMap).toEqual({0: 0, 65: 2, 128512: 1});
    });

    it('keeps a BMP table within the maximum format 4 segment budget', () => {
        const glyphs = [];
        for (let i = 0; i < 8188; i += 1) {
            const code = i * 2;
            glyphs.push({unicode: code, unicodes: [code]});
        }
        const cmap = makeCmapTable(glyphSet(glyphs));

        expect(cmap.numTables).toBe(1);
        expect(cmap.format).toBe(4);
        expect(cmap.cmap4Length).toBe(65528);
        expect(cmap.cmap4Length).toBeLessThanOrEqual(0xFFFF);
        expect(cmap.segCountX2).toBe(8189 * 2);
    });

    it('falls back to a terminator-only format 4 when the BMP segment budget overflows', () => {
        const glyphs = [];
        for (let i = 0; i < 8190; i += 1) {
            const code = i * 2;
            glyphs.push({unicode: code, unicodes: [code]});
        }
        const cmap = makeCmapTable(glyphSet(glyphs));

        expect(cmap.numTables).toBe(2);
        expect(cmap.offset).toBe(20);
        expect(cmap.cmap12PlatformID).toBe(3);
        expect(cmap.cmap12EncodingID).toBe(10);
        expect(cmap.cmap4Length).toBe(24);
        expect(cmap.segCountX2).toBe(2);
        expect(cmap.fields.find((field) => field.name === 'cmap12Length').value).toBe(98296);
        expect(cmap.fields.find((field) => field.name === 'cmap12nGroups').value).toBe(8190);
        expect(cmap.cmap12Offset).toBe(44);
        expect(cmap.fields.filter((field) => field.name.startsWith('end_')).length).toBe(1);
        expect(cmap.fields.find((field) => field.name === 'end_8190').value).toBe(0xFFFF);
    });
});

