        const sfntTable = sfnt.fontToTable(createBaseFont());
        const records = getTableRecords(sfntTable);
        const tags = records.map((record) => record.tag);

        expect(sfntTable.tableName).toBe('sfnt');
        expect(sfntTable.version).toBe('OTTO');
        expect(sfntTable.numTables).toBe(records.length);
        expect(tags).toEqual([...tags].sort());
        expect(tags).toEqual(expect.arrayContaining([
            'CFF ', 'OS/2', 'cmap', 'head', 'hhea', 'hmtx',
            'ltag', 'maxp', 'name', 'post'
        ]));
        expect(tags).not.toContain('gasp');
        expect(tags).not.toContain('meta');

        const directoryEnd = 12 + 16 * records.length;
        records.forEach((record) => {
            expect(record.offset % 4).toBe(0);
            expect(record.offset).toBeGreaterThanOrEqual(directoryEnd);
            expect(record.length).toBe(getTable(sfntTable, record.tag).sizeOf());
        });
        expect(new Set(records.map((record) => record.offset)).size).toBe(records.length);

        records.forEach((record) => {
            const tableData = getTable(sfntTable, record.tag);
            if (record.tag === 'head') {
                const headTable = tableData;
                const adjustment = headTable.checkSumAdjustment;
                let expected;
                headTable.checkSumAdjustment = 0;
                try {
                    expected = sfnt.computeCheckSum(headTable.encode());
                } finally {
                    headTable.checkSumAdjustment = adjustment;
                }
                expect(record.checkSum).toBe(expected);
            } else {
                expect(record.checkSum).toBe(sfnt.computeCheckSum(tableData.encode()));
            }
        });

        expect(sfntTable.sizeOf()).toBe(sfntTable.encode().length);
        expect(sfnt.computeCheckSum(sfntTable.encode())).toBe(0xB1B0AFBA);
    });

    test('derives head, hhea, maxp, and hmtx values from the glyph set', () => {
        const sfntTable = sfnt.fontToTable(createBaseFont());
        const headTable = getTable(sfntTable, 'head');
        const hheaTable = getTable(sfntTable, 'hhea');
        const maxpTable = getTable(sfntTable, 'maxp');
        const hmtxTable = getTable(sfntTable, 'hmtx');

        expect(headTable).toMatchObject({
            unitsPerEm: 1000,
            xMin: 0,
            yMin: 0,
            xMax: 630,
            yMax: 700,
            flags: 3,
            lowestRecPPEM: 3,
            macStyle: 0,
            created: 1700000000 + 2082844800
        });
        expect(headTable.checkSumAdjustment).toBeGreaterThan(0);

        expect(hheaTable).toMatchObject({
            ascender: 800,
            descender: -200,
            advanceWidthMax: 650,
            minLeftSideBearing: 0,
            minRightSideBearing: 0,
            xMaxExtent: 650,
            numberOfHMetrics: 5
        });
        expect(maxpTable.numGlyphs).toBe(5);

        expect(hmtxTable.sizeOf()).toBe(20);
        expect(hmtxTable.fields
            .filter((field) => field.name.startsWith('advanceWidth_'))
            .map((field) => field.value)).toEqual([500, 250, 600, 400, 650]);
        expect(hmtxTable.fields
            .filter((field) => field.name.startsWith('leftSideBearing_'))
            .map((field) => field.value)).toEqual([0, 0, 10, 5, 20]);
    });

    test('reflects character coverage and glyph metrics in the OS/2 table', () => {
        const os2Table = getTable(sfnt.fontToTable(createBaseFont()), 'OS/2');

        expect(os2Table).toMatchObject({
            xAvgCharWidth: 475,
            usFirstCharIndex: 32,
            usLastCharIndex: 120,
            ulUnicodeRange1: 1,
            ulUnicodeRange2: 0,
            sTypoAscender: 800,
            sTypoDescender: -200,
            sTypoLineGap: 0,
            usWinAscent: 700,
            usWinDescent: 0,
            ulCodePageRange1: 1,
            sxHeight: 500,
            sCapHeight: 700,
            usDefaultChar: 32,
            usBreakChar: 32
        });
    });

    test('uses fallback OS/2 metrics and no default character when preferred glyphs are absent', () => {
        const font = createFont([
            makeGlyph('.notdef', undefined, 500, 0),
            makeGlyph('z', 122, 500, 0, [0, 0, 300, 400])
        ], {
            ascender: 900,
            descender: -300
        });

