        expect(tags).toContain('meta');
        expect(gaspTable.numRanges).toBe(2);
        expect(gaspTable.fields.slice(2).map((field) => field.value))
            .toEqual([8, 1, 65535, 3]);
        expect(metaTable.numTags).toBe(2);
