        expect(getNameRecordString(nameTable, 3, 2)).toBe('Regular');
        expect(getNameRecordString(nameTable, 3, 3)).toBe('Acme Type: Test Family Regular');
        expect(getNameRecordString(nameTable, 3, 4)).toBe('Test Family Regular');
        expect(getNameRecordString(nameTable, 3, 6)).toBe('TestFamilyRegular');
    });

