            ],
            sharedPoints: [],
        };
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 }).map((p) => p.x))
            .toEqual([15, 65, 115]);
    });

    test('delegates composite glyphs to component transformation', () => {
        const firstComponentGlyph = { index: 0, points: [point(10, 10), point(20, 20)] };
        const secondComponentGlyph = { index: 1, points: [point(10, 10), point(20, 20)] };
