        const processor = new VariationProcessor(font);
        const glyph = {
            index: 5,
            isComposite: true,
            points: [point(0, 0), point(0, 0), point(0, 0), point(0, 0)],
            components: [
                { glyphIndex: 0, xScale: 1, scale01: 0, scale10: 0, yScale: 1, dx: 0, dy: 0 },
