describe('getBlendVector', () => {
    const axes = [axis('wght', -1, 0, 1)];
    function vectorFor(regionAxes, coords) {
        const processor = new VariationProcessor(makeFont({ axes }));
        return processor.getBlendVector(itemStore([region(regionAxes)], [[0]]), 0, coords);
    }

    test('returns one scalar per region', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const store = itemStore(
            [region([[0, 0.5, 1]]), region([[-1, -0.5, 0]])],
            [[1, 1]]
        );
        const blendVector = processor.getBlendVector(store, 0, { wght: 0.5 });
        expect(blendVector[0]).toBeCloseTo(1, 6);
        expect(blendVector[1]).toBe(0);
    });

    test('treats invalid axis ranges as fully selected', () => {
        expect(vectorFor([[1, 0.5, -1]], { wght: 0 })).toEqual([1]);
    });

    test('ignores regions spanning zero when the peak is non-zero', () => {
        expect(vectorFor([[-1, 0.5, 1]], { wght: 0.5 })).toEqual([1]);
    });

    test('ignores regions with a zero peak', () => {
        expect(vectorFor([[-1, 0, 1]], { wght: 0.5 })).toEqual([1]);
    });

    test('returns zero outside the region range', () => {
        expect(vectorFor([[0.2, 0.5, 0.8]], { wght: 0.1 })).toEqual([0]);
        expect(vectorFor([[0.2, 0.5, 0.8]], { wght: 0.9 })).toEqual([0]);
    });

    test('returns one at the peak coordinate', () => {
        expect(vectorFor([[0.2, 0.5, 0.8]], { wght: 0.5 })[0]).toBeCloseTo(1, 6);
    });

    test('scales linearly below and above the peak', () => {
        const below = vectorFor([[0.2, 0.5, 0.8]], { wght: 0.35 })[0];
        expect(below).toBeCloseTo(0.5, 6);
        const above = vectorFor([[0.2, 0.5, 0.8]], { wght: 0.65 })[0];
        expect(above).toBeCloseTo(0.5, 6);
    });

    test('multiplies scalars across multiple axes', () => {
        const processor = new VariationProcessor(makeFont({
            axes: [axis('wght', -1, 0, 1), axis('wdth', -1, 0, 1)],
        }));
        const store = itemStore([region([[0, 0.5, 1], [0, 0.5, 1]])], [[1]]);
        expect(processor.getBlendVector(store, 0, { wght: 0.5, wdth: 0.25 })[0]).toBeCloseTo(0.5, 6);
    });

    test('falls back to the font variation coordinates', () => {
        const processor = new VariationProcessor(makeFont({ axes, coords: { wght: 0.5 } }));
        const store = itemStore([region([[0, 0.5, 1]])], [[1]]);
        expect(processor.getBlendVector(store, 0)[0]).toBeCloseTo(1, 6);
    });
});

