describe('getVariableAdjustment', () => {
    const axes = [axis('wght', -1, 0, 1)];

    function hvarFor(mapSize = 0) {
        const store = itemStore([region([[0, 1, 1]])], [[10], [20], [30]]);
        const hvar = { itemVariationStore: store };
        if (mapSize) {
            hvar.advanceWidth = { map: Array.from({ length: mapSize }, (_, i) => ({ outerIndex: 0, innerIndex: i })) };
        }
        return hvar;
    }

    test('throws when the requested table is missing', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        expect(() => processor.getVariableAdjustment(0, 'hvar', 'advanceWidth', { wght: 1 }))
            .toThrow(/non-existent table/);
    });

    test('throws when the table has no item variation store', () => {
        const processor = new VariationProcessor(makeFont({ axes, hvar: {} }));
        expect(() => processor.getVariableAdjustment(0, 'hvar', 'advanceWidth', { wght: 1 }))
            .toThrow(/does not have an itemVariationStore/);
    });

    test('uses the glyph id as the inner index when no map exists', () => {
        const processor = new VariationProcessor(makeFont({ axes, hvar: hvarFor() }));
        expect(processor.getVariableAdjustment(1, 'hvar', 'advanceWidth', { wght: 1 })).toBeCloseTo(20, 6);
    });

    test('uses the delta set index map for the requested glyph', () => {
        const processor = new VariationProcessor(makeFont({ axes, hvar: hvarFor(3) }));
        expect(processor.getVariableAdjustment(2, 'hvar', 'advanceWidth', { wght: 1 })).toBeCloseTo(30, 6);
    });

    test('clamps glyph ids beyond the end of the map', () => {
        const processor = new VariationProcessor(makeFont({ axes, hvar: hvarFor(2) }));
        expect(processor.getVariableAdjustment(100, 'hvar', 'advanceWidth', { wght: 1 })).toBeCloseTo(20, 6);
    });

    test('falls back to font variation coordinates', () => {
        const processor = new VariationProcessor(makeFont({ axes, hvar: hvarFor(), coords: { wght: 1 } }));
        expect(processor.getVariableAdjustment(0, 'hvar', 'advanceWidth')).toBeCloseTo(10, 6);
    });
});

