    });

    test('uses getBlendPath for CFF2 glyphs without points', () => {
        const blendPath = { commands: [{ type: 'M', x: 1, y: 2 }] };
        const getBlendPath = jest.fn(() => blendPath);
        const glyph = { index: 6, name: 'cff2', advanceWidth: 400, getBlendPath };
        const processor = new VariationProcessor(makeFont({ axes }));
        const result = processor.getTransform(glyph, { wght: 0.5 });
        expect(result).not.toBe(glyph);
        expect(typeof result.getBoundingBox).toBe('function');
        expect(result.path).toBe(blendPath);
        expect(getBlendPath).toHaveBeenCalledWith({ wght: 0.5 });
    });

    test('adjusts hvar advance width and left side bearing', () => {
        const hvar = {
            itemVariationStore: itemStore([region([[0, 1, 1]])], [[10], [20]]),
            advanceWidth: { map: [{ outerIndex: 0, innerIndex: 0 }] },
            lsb: { map: [{ outerIndex: 0, innerIndex: 1 }] },
        };
        const glyph = { index: 0, advanceWidth: 500, leftSideBearing: 20 };
        const processor = new VariationProcessor(makeFont({ axes, glyphs: { 0: glyph }, hvar }));
        const result = processor.getTransform(glyph, { wght: 1 });
        expect(result.advanceWidth).toBe(510);
        expect(result.leftSideBearing).toBe(40);
        expect(glyph.advanceWidth).toBe(510);
        expect(glyph.leftSideBearing).toBe(40);
        expect(glyph._advanceWidth).toBe(500);
        expect(glyph._leftSideBearing).toBe(20);
    });

    test('keeps the original base metrics when hvar is applied repeatedly', () => {
        const hvar = {
            itemVariationStore: itemStore([region([[0, 1, 1]])], [[10], [20]]),
            advanceWidth: { map: [{ outerIndex: 0, innerIndex: 0 }] },
            lsb: { map: [{ outerIndex: 0, innerIndex: 1 }] },
        };
        const glyph = { index: 0, advanceWidth: 500, leftSideBearing: 20 };
        const processor = new VariationProcessor(makeFont({ axes, glyphs: { 0: glyph }, hvar }));
        processor.getTransform(glyph, { wght: 1 });
        processor.getTransform(glyph, { wght: 1 });
        expect(glyph.advanceWidth).toBe(510);
        expect(glyph.leftSideBearing).toBe(40);
    });
});

describe('integration with real variable font fixtures', () => {
    test('gvar transformation changes glyph outlines at a non-default axis value', () => {
        const font = parseFixture('TestGVAROne.ttf');
        const glyphIndex = 0;
        const glyph = font.glyphs.get(glyphIndex);
        const originalPoints = glyph.points.map((p) => Object.assign({}, p));

        const defaultGlyph = font.variation.process.getTransform(glyphIndex, { wght: 400 });
        const boldGlyph = font.variation.process.getTransform(glyphIndex, { wght: 700 });

        expect(defaultGlyph.points).toHaveLength(glyph.points.length);
        expect(boldGlyph.points).toHaveLength(glyph.points.length);
        expect(boldGlyph.points).not.toEqual(defaultGlyph.points);
        expect(boldGlyph.points.every((p, i) => p.onCurve === originalPoints[i].onCurve
            && p.lastPointOfContour === originalPoints[i].lastPointOfContour)).toBe(true);
        expect(glyph.points).toEqual(originalPoints);
    });

    test('hvar adjusts the advance width and side bearing of a real variable glyph', () => {
        const font = parseFixture('Changa-VariableFont_wght.ttf');
        const glyph = font.glyphs.get(1);
        const baseAdvanceWidth = glyph.advanceWidth;
        const baseLeftSideBearing = glyph.leftSideBearing;

        const transformed = font.variation.process.getTransform(1, { wght: 800 });

        expect(transformed.advanceWidth).toBeGreaterThan(baseAdvanceWidth);
        expect(transformed.leftSideBearing).toBeGreaterThan(baseLeftSideBearing);
        expect(glyph._advanceWidth).toBe(baseAdvanceWidth);
        expect(glyph._leftSideBearing).toBe(baseLeftSideBearing);
        expect(glyph.advanceWidth).toBe(transformed.advanceWidth);
        expect(glyph.leftSideBearing).toBe(transformed.leftSideBearing);
    });

    test('cvar transform leaves the default CVT unchanged and applies deltas at a non-default axis value', () => {
        const font = parseFixture('TestCVARGVAROne.ttf');
        const originalCvt = font.tables.cvt.slice();

        const defaultCvt = font.variation.process.getCvarTransform({ wght: 94 });
        expect(defaultCvt).toEqual(originalCvt);

        const boldCvt = font.variation.process.getCvarTransform({ wght: 194 });
        expect(boldCvt).toHaveLength(originalCvt.length);
        expect(boldCvt).not.toEqual(originalCvt);
        expect(originalCvt[66]).toBe(94);
        expect(boldCvt[66]).toBe(194);
        expect(font.tables.cvt).toEqual(originalCvt);
    });
});
